# User Registration and Profile Management System

class User:
    def __init__(self, username, email, password, cultural_background, interests):
        self.username = username
        self.email = email
        self.password = password
        self.cultural_background = cultural_background
        self.interests = interests
        self.profile_picture = None

    def upload_profile_picture(self, picture_path):
        self.profile_picture = picture_path

    def update_profile(self, cultural_background=None, interests=None):
        if cultural_background:
            self.cultural_background = cultural_background
        if interests:
            self.interests = interests


class UserProfileManager:
    def __init__(self):
        self.users = {}

    def register_user(self, username, email, password, cultural_background, interests):
        if username in self.users:
            return False, "Username already exists."
        self.users[username] = User(username, email, password, cultural_background, interests)
        return True, "User registered successfully."

    def get_user(self, username):
        return self.users.get(username, None)

    def update_user_profile(self, username, cultural_background=None, interests=None):
        user = self.get_user(username)
        if not user:
            return False, "User not found."
        user.update_profile(cultural_background, interests)
        return True, "Profile updated successfully."

    def upload_profile_picture(self, username, picture_path):
        user = self.get_user(username)
        if not user:
            return False, "User not found."
        user.upload_profile_picture(picture_path)
        return True, "Profile picture uploaded successfully."


