class VirtualTour:
    def __init__(self, landmark_name, location, description, audio_guide=None, hotspots=None):
        self.landmark_name = landmark_name
        self.location = location
        self.description = description
        self.audio_guide = audio_guide
        self.hotspots = hotspots or []

    def add_hotspot(self, name, description, media=None):
        self.hotspots.append({"name": name, "description": description, "media": media})

    def play_audio_guide(self):
        if self.audio_guide:
            print(f"Playing audio guide for {self.landmark_name}...")
        else:
            print("No audio guide available for this tour.")

    def show_hotspots(self):
        print(f"Hotspots for {self.landmark_name}:")
        for hotspot in self.hotspots:
            print(f"- {hotspot['name']}: {hotspot['description']}")


class VirtualTourManager:
    def __init__(self):
        self.tours = {}

    def add_tour(self, tour_id, landmark_name, location, description, audio_guide=None, hotspots=None):
        self.tours[tour_id] = VirtualTour(landmark_name, location, description, audio_guide, hotspots)

    def get_tour(self, tour_id):
