from file_name_1 import UserProfileManager
from file_name_2 import VirtualTourManager
from file_name_3 import LanguageLearningManager
from file_name_4 import WorkshopManager
from file_name_5 import FeedbackManager


class CulturalExchangeHub:
    def __init__(self):
        self.user_profile_manager = UserProfileManager()
        self.virtual_tour_manager = VirtualTourManager()
        self.language_learning_manager = LanguageLearningManager()
        self.workshop_manager = WorkshopManager()
        self.feedback_manager = FeedbackManager()

    def run(self):
        print("Welcome to CulturalExchangeHub!")
        # Example usage
        self.user_profile_manager.register_user("alice", "alice@example.com", "password123", "American", ["music", "food"])
        self.virtual_tour_manager.add_tour(1, "Eiffel Tower", "Paris, France", "Iconic landmark of Paris.", "eiffel_tower_audio.mp3")
        self.virtual_tour_manager.get_tour(1).add_hotspot("History", "Built in 1889.")
        self.virtual_tour_manager.get_tour(1).play_audio_guide()
        self.virtual_tour_manager.get_tour(1).show_hotspots()

        self.language_learning_manager.create_exchange(1, "alice", "bob", "Spanish")
        exchange = self.language_learning_manager.get_exchange(1)
        exchange.start_exchange()
        print(exchange.translate_message("Hello, how are you?", "Spanish", "English"))

        self.workshop_manager.add_workshop(1, "Japanese Tea Ceremony", "Learn the art of Japanese tea ceremony.", "Sakura Sensei", "2025-04-05 14:00")
        workshop = self.workshop_manager.get_workshop(1)
        workshop.join_workshop("alice")
        workshop.ask_question("alice", "What is the significance of the tea ceremony?")
        workshop.start_session()

        self.feedback_manager.submit_feedback(1, "alice", "Great virtual tour experience!", 5)
        print(self.feedback_manager.get_feedback(1).content)

if __name__ == "__main__":
    hub = CulturalExchangeHub()
    hub.run()"
